        id: "qv8uhe",
        title: "Notes on his poem “From the Latin of Milton’s <i>De Idea Platonica Quemadmodum Aristoteles Intellexit</i>”",
        printedIn: "<i>English: Journal of the English Association</i>",
        issueOrVolume: "vol. 5, no. 30",
